/* Leçons pas à pas de raisonnement et ensembles (HAX101X, Simon Modeste). CC2 le vendredi 4 décembre à 15h, 1 h, aucun document.
   Le CC1 du 5/11 a été neutralisé : ce CC2 compte pour 55 % de la note (le CC3, les exercices de formalisation en ligne, 45 %).
   Programme retenu (rien d'annoncé au 11 novembre) : tout le cours (logique, raisonnements, ensembles, applications),
   comme les CC de novembre 2023, 2024 et 2025. Chaque leçon se termine par un exercice de TD ou de CC, à faire sur papier. */
(function(){
const LES=window.LESSONS=window.LESSONS||{};
const L=(h,x,o)=>Object.assign({k:"learn",h,x},o||{});
const Q=(q,o,a,e,x)=>Object.assign({k:"qcm",q,o,a,e},x||{});
const S=(h,intro,s,x)=>Object.assign({k:"steps",h,intro,s},x||{});
const P=(h,x,sol,check,min,o)=>Object.assign({k:"paper",h,x,sol,check,min},o||{});
const K=(f,b)=>({k:"card",f,b});
const box=s=>`<div class="formula">${s}</div>`;
const tv=(head,rows)=>`<div style="overflow-x:auto"><table class="tbl tv"><thead><tr>${head.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;

LES.rai=[
/* ------------------------------------------------------------------ */
{id:"r-logique",t:"Propositions, connecteurs, tables de vérité",min:14,goal:"Calculer la valeur de vérité d'une phrase composée, surtout d'une implication (TD 1, ex. 3, 5, 6, 8).",steps:[
 Q("« Si 2 + 2 = 5, alors 1 = 2. » Cette phrase est-elle vraie ?",["Oui : une implication dont l'hypothèse est fausse est vraie","Non : sa conclusion 1 = 2 est fausse","On ne peut pas savoir : l'hypothèse 2 + 2 = 5 n'arrive jamais","Non : une hypothèse fausse rend toute la phrase fausse"],0,"P ⇒ Q n'est fausse que si P est vraie et Q fausse. Ici P est fausse : l'implication est vraie."),
 L("Les connecteurs",`<p>Une <b>proposition</b> est un énoncé vrai ou faux. On les combine avec non (¬), et (∧), ou (∨), implique (⇒), équivaut (⇔).</p>${tv(["P","Q","P et Q","P ou Q","P ⇒ Q","P ⇔ Q"],[["V","V","V","V","V","V"],["V","F","F","V","<b>F</b>","F"],["F","V","F","V","V","F"],["F","F","F","F","V","V"]])}<ul><li>« ou » est <b>inclusif</b> : vrai si l'un des deux, ou les deux.</li><li><b>P ⇒ Q est fausse seulement quand P est vraie et Q fausse</b>. Elle a la même table que (non P) ou Q.</li></ul>`),
 Q("« Si 2 &lt; 3, alors 1 = 0. » Valeur de vérité ?",["Faux : hypothèse vraie, conclusion fausse","Vrai : 2 &lt; 3 est vrai","Ni l'un ni l'autre : 2 &lt; 3 et 1 = 0 n'ont aucun rapport","Vrai : une implication est vraie dès que l'une des deux parties l'est"],0,"Vrai ⇒ Faux, c'est le seul cas où l'implication est fausse (TD 1, ex. 3c). Le lien de sens entre les deux phrases ne compte pas : seules leurs valeurs de vérité comptent."),
 L("Équivalences et lois de De Morgan",`<p>Deux propositions sont <b>équivalentes</b> (≡) si elles ont la même table de vérité.</p>${box("non(P et Q) ≡ (non P) ou (non Q)        non(P ou Q) ≡ (non P) et (non Q)")}<ul><li>P ⇔ Q ≡ (P ⇒ Q) et (Q ⇒ P) ≡ (P et Q) ou (non P et non Q) ≡ (non P ⇔ non Q).</li><li>non(P ⇒ Q) ≡ P et (non Q).</li><li>« et » et « ou » sont distributifs l'un sur l'autre : P et (Q ou R) ≡ (P et Q) ou (P et R).</li></ul>`),
 Q("Laquelle est équivalente à P ⇔ Q ?",["(P ⇒ Q) et (Q ⇒ P)","non(P et non Q)","(P ⇒ Q) et (non Q ⇒ non P)","(P ou non P) ⇒ (Q ou non Q)"],0,"Les deux sens. « non(P et non Q) » et « (P ⇒ Q) et (non Q ⇒ non P) » ne disent que P ⇒ Q ; « (P ou non P) ⇒ (Q ou non Q) » est toujours vraie (TD 1, ex. 6)."),
 Q("(P et Q) ou R, et P et (Q ou R) : sont-elles équivalentes ?",["Non : avec P faux et R vrai, la 1ʳᵉ est vraie et la 2ᵉ fausse","Oui : on a seulement déplacé les parenthèses","Oui : « et » se distribue sur « ou », comme × sur +"],0,"Une seule ligne de table de vérité différente suffit (TD 1, ex. 8). « et » se distribue bien sur « ou », mais ça donne (P et Q) ou (P et R), pas (P et Q) ou R."),
 P("TD 1, exercice 3, sur papier",`<p>Traduire les énoncés suivants en langage mathématique, et déterminer leur valeur de vérité compte-tenu de la valeur des propositions qui les composent :</p><p>(a) 12 est divisible par 2 ou par 4.<br>(b) 12 est divisible par 2 et par 5.<br>(d) Si 3 + 2 = 5 alors 4 + 4 = 8.<br>(e) Il est faux que si 2 + 2 = 5 alors 1 = 2.<br>(f) Si 18 est un nombre premier, alors 18 n'est pas divisible par 5.<br>(g) Si 13 est pair, alors 26 est divisible par 4.<br>(h) 110 est divisible par 10 si et seulement si il est divisible par 2 et par 5.<br>(i) 18 est un nombre pair si et seulement si 18 est divisible par 2 et par 7.<br>(j) Si 22 est un nombre premier, alors si 11 ≠ 1 et 11 ≠ 22, 11 n'est pas un diviseur de 22.</p><p>(La phrase (c) du même exercice vient d'être vue.) « Traduire » veut dire ici : nommer P, Q, R les propositions simples, et écrire la phrase avec « et », « ou », « non », ⇒, ⇔.</p>`,`<p>On note P, Q, R les propositions simples, dans l'ordre où elles apparaissent.</p><p><b>(a)</b> P ou Q, avec P : « 12 est divisible par 2 » (vraie) et Q : « 12 est divisible par 4 » (vraie). <b>Vrai.</b></p><p><b>(b)</b> P et Q, avec Q : « 12 est divisible par 5 » (fausse). <b>Faux.</b></p><p><b>(d)</b> P ⇒ Q, avec P : « 3 + 2 = 5 » (vraie) et Q : « 4 + 4 = 8 » (vraie). <b>Vrai.</b></p><p><b>(e)</b> non(P ⇒ Q), avec P : « 2 + 2 = 5 » (fausse) et Q : « 1 = 2 » (fausse). P ⇒ Q est vraie, car P est fausse. Sa négation est donc <b>fausse</b>.</p><p><b>(f)</b> P ⇒ non Q, avec P : « 18 est premier » (fausse). Une implication dont l'hypothèse est fausse est <b>vraie</b>.</p><p><b>(g)</b> P ⇒ Q, avec P : « 13 est pair » (fausse). <b>Vrai</b>, même si « 26 est divisible par 4 » est fausse.</p><p><b>(h)</b> P ⇔ (Q et R), avec P : « 110 est divisible par 10 » (vraie), Q : « par 2 » (vraie), R : « par 5 » (vraie). Vrai ⇔ vrai : <b>vrai</b>.</p><p><b>(i)</b> P ⇔ (Q et R), avec P : « 18 est pair » (vraie), Q : « 18 est divisible par 2 » (vraie), R : « par 7 » (fausse). « Q et R » est fausse. Vrai ⇔ faux : <b>faux</b>.</p><p><b>(j)</b> P ⇒ ((Q et R) ⇒ non S), avec P : « 22 est premier » (fausse), Q : « 11 ≠ 1 », R : « 11 ≠ 22 », S : « 11 est un diviseur de 22 ». Comme P est fausse, l'implication est <b>vraie</b>, quoi qu'il y ait après.</p>`,["Chaque phrase est d'abord écrite avec P, Q, R et les connecteurs","La valeur de chaque proposition simple est donnée","(e), (f), (g), (j) : l'hypothèse est fausse, donc l'implication est vraie","(i) : « Q et R » est fausse, donc l'équivalence est fausse"],10),
 K("Dans quel cas l'implication P ⇒ Q est-elle fausse ?","Seulement quand P est vraie et Q fausse. P ⇒ Q ≡ (non P) ou Q ; non(P ⇒ Q) ≡ P et non Q."),
 K("Que disent les lois de De Morgan sur non(P et Q) et sur non(P ou Q) ?","non(P et Q) ≡ non P ou non Q ; non(P ou Q) ≡ non P et non Q.")]},

/* ------------------------------------------------------------------ */
{id:"r-quantif",t:"Quantificateurs : traduire et nier",min:14,goal:"Écrire une phrase avec ∀ et ∃, et écrire sa négation (CC2 2023-2024, ex. 1 et 2 ; TD 1, ex. 1, 2, 7, 12, 17).",steps:[
 Q("Négation de « tous les étudiants ont réussi » ?",["Au moins un étudiant n'a pas réussi","Aucun étudiant n'a réussi","Tous les étudiants ont échoué"],0,"non(∀x, P(x)) = ∃x, non P(x) : il suffit d'un contre-exemple."),
 L("Traduire avec ∀ et ∃",`<ul><li>∀x ∈ E, P(x) : pour tout x de E, P(x). ∃x ∈ E, P(x) : il existe au moins un x de E tel que P(x).</li><li>« Au moins deux solutions » : ∃x, ∃y, x ≠ y et (x solution) et (y solution).</li><li>L'ordre compte : « ∀x, ∃y » (y peut dépendre de x) n'est pas « ∃y, ∀x » (un même y pour tous).</li></ul>${box("Goldbach : ∀n ∈ ℕ, (Pair(n) et n &gt; 3) ⇒ (∃p ∈ ℕ, ∃q ∈ ℕ, Prem(p) et Prem(q) et n = p + q)")}<p>« Tout … qui … » se traduit par ∀ avec une <b>implication</b> : « tout entier pair supérieur à 3 » = ∀n, (Pair(n) et n &gt; 3) ⇒ ….</p>`),
 Q("« L'équation eˣ − x³ = 2 a au moins deux solutions réelles distinctes » s'écrit…",["∃x ∈ ℝ, ∃y ∈ ℝ, x ≠ y et eˣ − x³ = 2 et eʸ − y³ = 2","∀x ∈ ℝ, eˣ − x³ = 2","∃x ∈ ℝ, eˣ − x³ = 2 et eˣ − x³ = 2"],0,"Deux éléments, différents, qui vérifient tous les deux l'équation (TD 1, ex. 7)."),
 L("Nier une phrase quantifiée",`<p>On parcourt la phrase de gauche à droite : chaque ∀ devient ∃, chaque ∃ devient ∀, et on nie la fin (le domaine ∈ ne change pas).</p>${box("non(∀x ∈ ℝ, ∀ε &gt; 0, ∃y ∈ ℚ, x &lt; y &lt; x + ε)  =  ∃x ∈ ℝ, ∃ε &gt; 0, ∀y ∈ ℚ, (y ≤ x ou y ≥ x + ε)")}<ul><li>non(a &lt; y &lt; b) = (y ≤ a ou y ≥ b) : la double inégalité est un « et ».</li><li>non(P ⇒ Q) = P et non Q : « tous ceux qui ont les yeux bleus gagneront » se nie en « il y a quelqu'un qui a les yeux bleus et qui ne gagnera pas ».</li></ul>`),
 Q("Négation de « ∀x ∈ ℝ, ∃y ∈ ℝ, f(x) ≤ g(y) » ?",["∃x ∈ ℝ, ∀y ∈ ℝ, f(x) &gt; g(y)","∃x ∈ ℝ, ∃y ∈ ℝ, f(x) &gt; g(y)","∀x ∈ ℝ, ∀y ∈ ℝ, f(x) &gt; g(y)"],0,"Chaque quantificateur change, et ≤ devient &gt; (TD 1, ex. 2b)."),
 S("Vrai ou faux avec A = {2, 3, 5, 6} et B = {1, 2, −3} (TD 1, ex. 10)","Dire si chaque phrase est vraie ou fausse : (a) ∀x ∈ A, ∃y ∈ B, x + y ∈ A ; (b) ∀x ∈ A, ∀y ∈ B, x + y ∈ A ; (c) ∃x ∈ A, ∀y ∈ B, x + y ∈ A ; (d) ∃x ∈ A, ∀y ∈ B, ∃z ∈ B, x + y + z ∈ A. On vérifie chaque phrase en suivant l'ordre des quantificateurs.",[
  {w:"∀x ∈ A, ∃y ∈ B, x + y ∈ A : vrai. 2 + 1 = 3, 3 + 2 = 5, 5 + 1 = 6, 6 − 3 = 3.",why:"Pour chaque x, on exhibe un y (qui peut changer avec x)."},
  {w:"∀x ∈ A, ∀y ∈ B, x + y ∈ A : faux. 2 + 2 = 4 ∉ A.",why:"Un contre-exemple suffit."},
  {w:"∃x ∈ A, ∀y ∈ B, x + y ∈ A : faux. Pour chaque x, un y fait sortir de A : 2 + 2, 3 + 1, 5 + 2, 6 + 1.",why:"Pour nier un ∃, il faut traiter tous les x."},
  {w:"∃x ∈ A, ∀y ∈ B, ∃z ∈ B, x + y + z ∈ A : vrai avec x = 3 : y = 1 → z = 1 (5) ; y = 2 → z = 1 (6) ; y = −3 → z = 2 (2).",why:"z peut dépendre de y."}]),
 P("TD 1, exercices 2 (a) et 15, sur papier",`<p><b>Exercice 2.</b> Écrire la négation de l'assertion (a) : (A ou B) ⇒ C. (La négation (b) vient d'être vue.)</p><p><b>Exercice 15.</b> On considère sur l'ensemble F des femmes, l'assertion P(x, y) = « x est la fille de y ». Formaliser avec des quantificateurs les phrases suivantes :</p><p>(a) Toute femme a une fille.<br>(b) Toute femme a une mère.<br>(c) Toutes les femmes ont une même mère.<br>(d) Toute femme est fille de toute femme.<br>(e) Il y a une femme qui est la fille de toute femme.<br>(f) On peut trouver deux femmes dont l'une est la fille de l'autre.</p>`,`<p><b>Exercice 2 (a).</b> La négation de « P ⇒ Q » est « P et non Q ». Ici P est « A ou B » et Q est « C ». <b>Négation : (A ou B) et non(C).</b></p><p><b>Exercice 15.</b> Dans P(x, y), la fille est x et la mère est y.</p><p><b>(a)</b> ∀y ∈ F, ∃x ∈ F, P(x, y). (Pour toute femme y, il existe une femme x qui est sa fille.)</p><p><b>(b)</b> ∀x ∈ F, ∃y ∈ F, P(x, y). (Pour toute femme x, il existe une femme y dont x est la fille.)</p><p><b>(c)</b> ∃y ∈ F, ∀x ∈ F, P(x, y). (Une même mère y pour toutes : le ∃y passe devant.)</p><p><b>(d)</b> ∀x ∈ F, ∀y ∈ F, P(x, y).</p><p><b>(e)</b> ∃x ∈ F, ∀y ∈ F, P(x, y).</p><p><b>(f)</b> ∃x ∈ F, ∃y ∈ F, P(x, y).</p><p>Compare (b) et (c) : ce sont les mêmes symboles, seul l'ordre de ∀ et ∃ change, et le sens n'a plus rien à voir.</p>`,["Ex. 2 : « P ⇒ Q » nié en « P et non Q », sans toucher au « ou »","Ex. 15 : dans P(x, y), la fille est x et la mère est y","(b) et (c) : les mêmes symboles, mais ∀ et ∃ dans l'ordre inverse","Chaque variable a son ensemble (∈ F)"],10),
 K("Comment écrit-on la négation d'une phrase qui contient des quantificateurs ∀ et ∃ ?","Chaque ∀ devient ∃ et inversement, dans le même ordre ; on nie la fin. non(a &lt; y &lt; b) = y ≤ a ou y ≥ b ; non(P ⇒ Q) = P et non Q."),
 K("Comment traduire avec des quantificateurs une phrase comme « tout entier pair supérieur à 3 vérifie … » ? (Pair(n) veut dire « n est pair ».)","∀n ∈ ℕ, (Pair(n) et n &gt; 3) ⇒ … : un ∀ suivi d'une implication.")]},

/* ------------------------------------------------------------------ */
{id:"r-preuves",t:"Prouver un ∀, un ∃, et rédiger",min:15,goal:"Savoir comment commencer chaque preuve, et prouver une propriété sur une fonction paire et croissante (TD 1, ex. 9 et 11).",steps:[
 Q("Pour montrer « ∀x ∈ ℝ, P(x) », on commence par…",["« Soit x ∈ ℝ. »","« Prenons x = 0. »","« Supposons qu'il existe x tel que P(x). »"],0,"On fixe un x quelconque, puis on montre P(x) pour ce x-là, sans rien supposer d'autre."),
 L("Comment commencer",`<ul><li><b>∀x ∈ E, P(x)</b> : « Soit x ∈ E », puis on prouve P(x). Pour réfuter : <b>un</b> contre-exemple.</li><li><b>∃x ∈ E, P(x)</b> : on <b>exhibe</b> un x (« Posons x = … ») et on vérifie. Pour réfuter : on montre non P(x) pour tout x.</li><li><b>P ⇒ Q</b> : « Supposons P », puis on montre Q.</li><li><b>P ⇔ Q</b> : deux sens, P ⇒ Q puis Q ⇒ P.</li><li><b>P et Q</b> : on prouve les deux. <b>P ou Q</b> : on suppose non P et on montre Q.</li></ul>${box("∀x ∈ ℕ, ∃y ∈ ℕ, y &gt; x³ :  « Soit x ∈ ℕ. Posons y = x³ + 1 ∈ ℕ. Alors y &gt; x³. »")}`),
 Q("Pour montrer « ∀x ∈ ℕ, ∃y ∈ ℕ, y &gt; x³ », on écrit…",["Soit x ∈ ℕ. Posons y = x³ + 1 : alors y &gt; x³.","Posons y = 1 : alors y &gt; x³ pour tout x.","Soit y ∈ ℕ. Posons x = 0."],0,"y est choisi après x et peut dépendre de x. y = 1 ne marche pas pour x = 1 (TD 1, ex. 9a)."),
 Q("« ∀x ∈ ℝ, x ∉ ℤ ⇒ x² ∉ ℚ » est-elle vraie ?",["Non : x = 1/2 n'est pas entier, mais x² = 1/4 ∈ ℚ","Oui : x = π le confirme, il n'est pas entier et π² n'est pas rationnel","Oui, par contraposée : x² ∈ ℚ entraîne x ∈ ℤ"],0,"La phrase est fausse. Contre-exemple : x = 1/2 n'est pas un entier, mais x² = 1/4 est un rationnel. Pour montrer qu'une phrase commençant par ∀ est fausse, un seul contre-exemple suffit (TD 1, ex. 9c)."),
 S("TD 1, exercice 11, question 2","L'énoncé : « Soit f : ℝ → ℝ une fonction. Démontrer (avec soin, comme toujours !) que si f est paire et croissante, alors elle est constante. » On montre que f(x) = f(0) pour tout réel x.",[
  {w:"Soit x ≥ 0. Comme 0 ≤ x et f est croissante : f(0) ≤ f(x).",why:"On applique la définition de « croissante » à 0 ≤ x."},
  {w:"Comme −x ≤ 0 : f(−x) ≤ f(0). Et f(−x) = f(x) car f est paire. Donc f(x) ≤ f(0).",why:"On applique la croissance à −x ≤ 0, puis la parité."},
  {w:"Donc f(x) = f(0) pour tout x ≥ 0.",why:"Deux inégalités dans les deux sens donnent l'égalité."},
  {w:"Si x &lt; 0 : f(x) = f(−x) avec −x &gt; 0, donc f(x) = f(0). Ainsi f est constante, égale à f(0).",why:"Disjonction de cas : x ≥ 0 puis x &lt; 0."}]),
 Q("Pour réfuter « ∃x ∈ A, ∀y ∈ B, x + y ∈ A », il faut…",["Montrer que pour chaque x de A, un y de B fait sortir de A","Trouver un seul x de A pour lequel un y de B fait sortir de A","Trouver un seul y de B qui fait sortir de A, quel que soit x"],0,"La négation est ∀x ∈ A, ∃y ∈ B, x + y ∉ A : il faut traiter tous les x. Un seul x ne suffit pas : la phrase dit « il existe x », il faut donc qu'aucun x ne marche."),
 P("TD 1, exercice 9 (d) et exercice 13 (a), sur papier",`<p><b>Exercice 9.</b> Vrai ou faux ? <b>Démontrer soigneusement.</b></p><p>(d) ∀x ∈ ℝ, ∀n ∈ ℕ, ((n est pair et x ≥ 0) ou (n est impair et x ≤ 0)) ⇒ (−1)ⁿx³ ≥ 0.</p><p>(Les assertions (a) et (c) viennent d'être vues ; la (b) attend la leçon suivante.)</p><p><b>Exercice 13.</b> Soit n un entier. L'assertion suivante est-elle vraie ou fausse ? <b>Démontrer soigneusement.</b></p><p>(a) Si n est impair, alors n² est impair.</p><p>Rappel, qui n'est pas dans le TD : « n est impair » veut dire qu'il existe un entier k tel que n = 2k + 1.</p>`,`<p><b>Exercice 9 (d) : vrai.</b> Soient x ∈ ℝ et n ∈ ℕ. Supposons (n pair et x ≥ 0) ou (n impair et x ≤ 0). On raisonne par disjonction de cas.<br>Premier cas : n est pair et x ≥ 0. Alors (−1)ⁿ = 1 et x³ ≥ 0, donc (−1)ⁿx³ = x³ ≥ 0.<br>Second cas : n est impair et x ≤ 0. Alors (−1)ⁿ = −1 et x³ ≤ 0, donc (−1)ⁿx³ = −x³ ≥ 0.<br>Dans les deux cas, (−1)ⁿx³ ≥ 0.</p><p><b>Exercice 13 (a) : vrai.</b> Supposons n impair : il existe un entier k tel que n = 2k + 1. Alors n² = 4k² + 4k + 1 = 2(2k² + 2k) + 1. Comme 2k² + 2k est un entier, n² est impair.</p><p>Répondre seulement « vrai » ne rapporte pas les points : l'énoncé demande de démontrer.</p>`,["« Soient x ∈ ℝ et n ∈ ℕ », puis « Supposons… » : la preuve commence ainsi","9 (d) : deux cas, et (−1)ⁿx³ ≥ 0 écrit dans chacun","13 (a) : n = 2k + 1, puis n² écrit sous la forme 2 × (un entier) + 1","Une phrase de conclusion"],10),
 K("Par quelle phrase commence-t-on la preuve d'un énoncé en ∀ ? En ∃ ? D'une implication ? D'une équivalence ?","∀ : « Soit x » ; ∃ : « Posons x = … » ; ⇒ : « Supposons P » ; ⇔ : les deux sens. Réfuter un ∀ : un contre-exemple."),
 K("Comment prouver un énoncé de la forme « P ou Q » ?","Supposer non P et montrer Q (ou l'inverse).")]},

/* ------------------------------------------------------------------ */
{id:"r-contraposee",t:"Contraposée, réciproque, absurde",min:13,goal:"Choisir le bon type de raisonnement : contraposée, absurde, disjonction de cas (TD 1, ex. 4, 13, 18 ; TD 2, ex. 1 et 7).",steps:[
 Q("La contraposée de « s'il pleut, alors le sol est mouillé » est…",["Si le sol n'est pas mouillé, alors il ne pleut pas","Si le sol est mouillé, alors il pleut","S'il ne pleut pas, alors le sol n'est pas mouillé"],0,"Contraposée de P ⇒ Q : non Q ⇒ non P. Elle est équivalente à P ⇒ Q. « Si le sol est mouillé, alors il pleut » est la réciproque, qui ne l'est pas."),
 L("Contraposée et réciproque",`${box("P ⇒ Q  ≡  non Q ⇒ non P   (contraposée)")}<ul><li>La contraposée est <b>équivalente</b> : la prouver suffit. Utile quand « non Q » donne une information plus simple.</li><li>La <b>réciproque</b> Q ⇒ P n'est <b>pas</b> équivalente.</li></ul><p>Exemple : « si n² est impair, alors n est impair ». Contraposée : « si n est pair, alors n² est pair ». n = 2k donne n² = 4k² = 2(2k²), pair.</p>`),
 Q("Contraposée de « ∀x ∈ ℝ, x² ∉ ℚ ⇒ x ∉ ℤ » ?",["∀x ∈ ℝ, x ∈ ℤ ⇒ x² ∈ ℚ","∀x ∈ ℝ, x ∉ ℤ ⇒ x² ∉ ℚ","∃x ∈ ℝ, x ∈ ℤ et x² ∉ ℚ"],0,"Le ∀ reste ; on échange et on nie les deux côtés de l'implication (TD 1, ex. 4b)."),
 L("Par l'absurde et par disjonction de cas",`<ul><li><b>Par l'absurde</b> : on suppose le <b>contraire</b> de ce qu'on veut, et on aboutit à une contradiction. Pour « ∀r ∈ A, r³ ∈ ℤ ⇒ r ≥ 0 », on suppose : « il existe r ∈ A, r &lt; 0, avec r³ ∈ ℤ ».</li><li><b>Disjonction de cas</b> : on sépare en cas qui couvrent tout (n pair / n impair ; x ≥ 0 / x &lt; 0).</li></ul><p>Exemple classique du cours : √2 est irrationnel (par l'absurde : √2 = p/q irréductible donne p² = 2q², donc p pair, puis q pair : contradiction).</p>`),
 Q("Pour prouver par l'absurde « ∀r ∈ A, r³ ∈ ℤ ⇒ r ≥ 0 », la première ligne est…",["On suppose qu'il existe r ∈ A, strictement négatif, dont le cube est un entier","On suppose que pour tout r ∈ A, r³ ∈ ℤ et r &lt; 0","On suppose qu'il existe r ∈ A positif dont le cube n'est pas entier"],0,"C'est la négation exacte : ∃r ∈ A, r³ ∈ ℤ et r &lt; 0 (TD 2, ex. 1).",{diag:false}),
 S("CC2 2025-2026, exercice 2","L'énoncé : « Démontrer que l'équation 9x⁵ − 11x⁴ + 6x − 5 = 0 n'admet pas de solution entière. (indication : on pourra raisonner sur la parité d'une telle solution) » Comme le corrigé officiel : par l'absurde, puis par disjonction de cas.",[
  {w:"Supposons qu'un entier x vérifie 9x⁵ − 11x⁴ + 6x − 5 = 0.",why:"Par l'absurde."},
  {w:"Si x est pair : 9x⁵, 11x⁴ et 6x sont pairs, donc 9x⁵ − 11x⁴ + 6x − 5 est impair.",why:"Pair − 5 = impair."},
  {w:"Si x est impair : 9x⁵ et 11x⁴ sont impairs, leur différence est paire ; 6x est pair ; donc le tout moins 5 est impair.",why:"Impair − impair = pair ; pair + pair − impair = impair."},
  {w:"Dans les deux cas, le membre de gauche est impair, donc non nul : contradiction. L'équation n'a pas de solution entière.",why:"0 est pair."}]),
 P("TD 2, exercice 7 (a) et TD 1, exercice 18, sur papier",`<p><b>TD 2, exercice 7.</b> Démontrer l'énoncé suivant : (a) Pour tout n ∈ ℤ, si n² − 1 n'est pas divisible par 8, alors n est pair.</p><p><b>TD 1, exercice 18</b> (examen 2017). Écrire la contraposée de l'assertion : « Pour tout n ∈ ℕ, si n² n'est pas un multiple de 3, alors n n'est pas un multiple de 3. » Démontrer l'assertion initiale.</p>`,`<p><b>TD 2, exercice 7 (a), par contraposée.</b> On montre : pour tout n ∈ ℤ, si n est impair, alors n² − 1 est divisible par 8. Soit n ∈ ℤ impair : il existe k ∈ ℤ tel que n = 2k + 1. Alors n² − 1 = 4k² + 4k = 4k(k + 1). Or k(k + 1) est le produit de deux entiers consécutifs : l'un des deux est pair, donc k(k + 1) = 2m avec m ∈ ℤ. Donc n² − 1 = 8m est divisible par 8. La contraposée est vraie, donc l'énoncé aussi.</p><p><b>TD 1, exercice 18.</b> Contraposée : « Pour tout n ∈ ℕ, si n est un multiple de 3, alors n² est un multiple de 3. »<br>On démontre la contraposée. Soit n ∈ ℕ. Supposons que n est un multiple de 3 : il existe k ∈ ℕ tel que n = 3k. Alors n² = 9k² = 3 × (3k²), et 3k² est un entier : n² est un multiple de 3. La contraposée est vraie. Comme une implication est équivalente à sa contraposée, l'assertion initiale est vraie.</p>`,["La contraposée est écrite avant la preuve","n écrit 2k + 1, puis 3k","Le produit de deux entiers consécutifs est pair : c'est justifié","La conclusion revient à l'énoncé de départ (« la contraposée est vraie, donc… »)"],12),
 K("Quelle est la contraposée de P ⇒ Q ? Et sa réciproque ? Laquelle des deux est équivalente à P ⇒ Q ?","non Q ⇒ non P, équivalente à P ⇒ Q. La réciproque Q ⇒ P ne l'est pas."),
 K("Comment fait-on un raisonnement par l'absurde ?","Supposer la négation exacte de ce qu'on veut (∀ devient ∃, P ⇒ Q devient P et non Q), puis trouver une contradiction.")]},

/* ------------------------------------------------------------------ */
{id:"r-recurrence",t:"La récurrence",min:15,goal:"Rédiger une récurrence complète, comme l'exercice 3 du CC 2024-2025 (divisibilité par 7).",steps:[
 Q("Pour prouver P(n) pour tout n ∈ ℕ par récurrence, il faut…",["P(0) et : pour tout n, P(n) ⇒ P(n + 1)","P(0) et P(1)","P(n) pour n = 0, 1, 2, 3"],0,"Initialisation et hérédité ; quelques exemples ne prouvent rien."),
 L("Le schéma",`<ol><li><b>Énoncer</b> P(n) clairement : « Pour n ∈ ℕ, notons P(n) : … ».</li><li><b>Initialisation</b> : vérifier P(0) (ou P(n₀) si on commence à n₀).</li><li><b>Hérédité</b> : « Soit n ∈ ℕ. Supposons P(n). Montrons P(n + 1). » On utilise P(n) dans le calcul.</li><li><b>Conclusion</b> : « Par récurrence, P(n) est vraie pour tout n ∈ ℕ. »</li></ol><p>Les deux étapes sont indispensables : une hérédité vraie ne prouve rien si l'initialisation est fausse. Tu le verras dans l'exercice sur papier de cette leçon.</p>`),
 Q("Quelle phrase commence correctement l'hérédité ?",["Soit n ∈ ℕ. Supposons P(n) et montrons P(n + 1).","Supposons P(n) vraie pour tout n.","Montrons P(n + 1) pour n = 0."],0,"On fixe un n et on suppose P(n) pour ce n seulement : supposer « pour tout n » serait supposer ce qu'on veut montrer.",{diag:false}),
 S("CC du 15 novembre 2024, exercice 3","L'énoncé : « Démontrer par récurrence l'énoncé suivant : ∀n ∈ ℕ, 3²ⁿ⁺² − 2ⁿ⁺¹ est divisible par 7. » La rédaction est celle du corrigé officiel.",[
  {w:"Initialisation : 3<sup>2×0+2</sup> − 2<sup>0+1</sup> = 9 − 2 = 7, qui est divisible par 7.",why:"On remplace n par 0."},
  {w:"Hérédité : soit n ∈ ℕ. On suppose que 3²ⁿ⁺² − 2ⁿ⁺¹ est divisible par 7.",why:"On fixe un n, et on suppose la propriété pour ce n seulement."},
  {w:"3<sup>2(n+1)+2</sup> − 2<sup>(n+1)+1</sup> = 3²ⁿ⁺⁴ − 2ⁿ⁺² = 3²ⁿ⁺² × 9 − 2ⁿ⁺¹ × 2.",why:"On écrit l'expression au rang n + 1, puis on fait apparaître les puissances du rang n."},
  {w:"= 3²ⁿ⁺² × 7 + 3²ⁿ⁺² × 2 − 2ⁿ⁺¹ × 2 = 7 × 3²ⁿ⁺² + 2(3²ⁿ⁺² − 2ⁿ⁺¹).",why:"L'astuce : 9 = 7 + 2. Le premier terme est un multiple de 7 ; la parenthèse est l'expression du rang n."},
  {w:"7 × 3²ⁿ⁺² est un multiple de 7, et 2(3²ⁿ⁺² − 2ⁿ⁺¹) aussi, par hypothèse de récurrence. Donc l'expression au rang n + 1 est un multiple de 7 : l'hérédité est vérifiée.",why:"La somme de deux multiples de 7 est un multiple de 7."},
  {w:"Conclusion, par récurrence : ∀n ∈ ℕ, 3²ⁿ⁺² − 2ⁿ⁺¹ est divisible par 7.",why:"La phrase finale est attendue."}]),
 Q("Dans cette hérédité, pourquoi écrire 9 = 7 + 2 ?",["Pour séparer un multiple de 7 et l'expression du rang n, qui est un multiple de 7 par hypothèse","Pour simplifier toute l'expression par 9, qui divise chaque terme","Pour revenir au cas n = 0, déjà vérifié à l'initialisation"],0,"3²ⁿ⁺² × 9 − 2ⁿ⁺¹ × 2 = 7 × 3²ⁿ⁺² + 2(3²ⁿ⁺² − 2ⁿ⁺¹) : on retrouve l'hypothèse de récurrence dans la parenthèse."),
 L("Inégalités par récurrence",`<p>Exemple (TD 2, ex. 9) : ∀n ∈ ℕ, 2ⁿ ≥ n.</p><ul><li>Initialisation : 2⁰ = 1 ≥ 0.</li><li>Hérédité : si 2ⁿ ≥ n, alors 2ⁿ⁺¹ = 2ⁿ + 2ⁿ ≥ n + 1, car 2ⁿ ≥ n et 2ⁿ ≥ 1.</li></ul><p>Inégalité de Bernoulli : pour x &gt; 0 et n ≥ 1, (1 + x)ⁿ ≥ 1 + nx. Hérédité : (1 + x)ⁿ⁺¹ = (1 + x)ⁿ(1 + x) ≥ (1 + nx)(1 + x) = 1 + (n + 1)x + nx² ≥ 1 + (n + 1)x. On a multiplié par 1 + x &gt; 0.</p>`),
 Q("Dans la preuve de Bernoulli, pourquoi peut-on multiplier l'inégalité par 1 + x ?",["Parce que 1 + x &gt; 0","Parce que n ≥ 1","On ne peut pas"],0,"Multiplier les deux côtés d'une inégalité par un nombre strictement positif garde le sens de l'inégalité ; par un nombre négatif, il faudrait l'inverser. Comme x &gt; 0, on a 1 + x &gt; 0 : on peut multiplier (1 + x)ⁿ ≥ 1 + nx par 1 + x sans changer le sens."),
 P("TD 2, exercice 9 (c) et exercice 10, sur papier",`<p><b>Exercice 9.</b> Montrer <b>par récurrence</b> la propriété suivante : (c) ∀n ∈ ℕ, 3ⁿ ≥ n². (Les propriétés (a) et (b) viennent d'être démontrées dans la leçon.)</p><p><b>Exercice 10.</b> Un étudiant souhaite démontrer par récurrence les énoncés suivants. Étudier l'initialisation et l'hérédité pour chacun d'eux. Que peut-on en conclure ?</p><p>(a) ∀n ∈ ℕ, ∃k ∈ ℕ, 4ⁿ − 1 = 3k.<br>(b) ∀n ∈ ℕ, ∃k ∈ ℕ, 4ⁿ + 1 = 3k.</p>`,`<p><b>Exercice 9 (c).</b> P(n) : « 3ⁿ ≥ n² ».<br><b>Initialisation.</b> 3⁰ = 1 ≥ 0, 3¹ = 3 ≥ 1 et 3² = 9 ≥ 4 : P(0), P(1) et P(2) sont vraies.<br><b>Hérédité, pour n ≥ 2.</b> Soit n ≥ 2 tel que P(n) est vraie. Alors 3ⁿ⁺¹ = 3 × 3ⁿ ≥ 3n². Il suffit de montrer 3n² ≥ (n + 1)², c'est-à-dire 2n² − 2n − 1 ≥ 0. Or 2n² − 2n − 1 = 2n(n − 1) − 1 ≥ 2 × 2 × 1 − 1 = 3 &gt; 0 pour n ≥ 2. Donc 3ⁿ⁺¹ ≥ (n + 1)² : P(n + 1) est vraie.<br><b>Conclusion.</b> P(0) et P(1) sont vraies, et P(n) est vraie pour tout n ≥ 2 par récurrence : pour tout n ∈ ℕ, 3ⁿ ≥ n².<br>(Pourquoi trois vérifications : pour n = 0 et n = 1, l'inégalité 3n² ≥ (n + 1)² est fausse, donc cette hérédité ne démarre qu'à n = 2.)</p><p><b>Exercice 10 (a).</b> Initialisation : 4⁰ − 1 = 0 = 3 × 0, vraie. Hérédité : soit n ∈ ℕ tel que 4ⁿ − 1 = 3k avec k ∈ ℕ. Alors 4ⁿ = 3k + 1 et 4ⁿ⁺¹ − 1 = 4(3k + 1) − 1 = 12k + 3 = 3(4k + 1), avec 4k + 1 ∈ ℕ : vraie. <b>L'énoncé (a) est démontré.</b></p><p><b>Exercice 10 (b).</b> Hérédité : soit n ∈ ℕ tel que 4ⁿ + 1 = 3k avec k ∈ ℕ. Alors 4ⁿ = 3k − 1 et 4ⁿ⁺¹ + 1 = 4(3k − 1) + 1 = 12k − 3 = 3(4k − 1) : l'hérédité est vraie. Initialisation : 4⁰ + 1 = 2, qui n'est pas un multiple de 3 : elle est <b>fausse</b>. On ne peut donc rien conclure par récurrence. Et en fait <b>l'énoncé (b) est faux pour tout n</b> : d'après (a), 4ⁿ + 1 = (4ⁿ − 1) + 2 = 3k + 2, qui n'est jamais un multiple de 3.</p><p><b>Conclusion.</b> Une hérédité vraie ne prouve rien toute seule : sans initialisation, la récurrence ne démarre pas.</p>`,["9 (c) : P(0), P(1) et P(2) vérifiées, et l'hérédité faite pour n ≥ 2","9 (c) : l'inégalité 3n² ≥ (n + 1)² est justifiée","10 : pour chaque énoncé, l'initialisation ET l'hérédité sont étudiées","10 (b) : hérédité vraie, initialisation fausse, donc rien n'est démontré","Une phrase de conclusion à chaque fois"],15),
 K("Quelles sont les quatre étapes d'une preuve par récurrence ?","Énoncer P(n) ; initialisation P(0) ; hérédité « Soit n, supposons P(n), montrons P(n + 1) » ; conclusion."),
 K("Par récurrence, on veut montrer que 3²ⁿ⁺² − 2ⁿ⁺¹ est divisible par 7. Dans l'hérédité, comment faire apparaître l'expression du rang n ?","Au rang n + 1, l'expression vaut 3²ⁿ⁺² × 9 − 2ⁿ⁺¹ × 2. On écrit 9 = 7 + 2 : cela donne 7 × 3²ⁿ⁺² + 2(3²ⁿ⁺² − 2ⁿ⁺¹), un multiple de 7 plus 2 fois l'expression du rang n.")]},

/* ------------------------------------------------------------------ */
{id:"r-ensembles",t:"Ensembles : écrire, appartenir, inclure",min:14,goal:"Ne plus confondre ∈ et ⊂, décrire un ensemble, lister P(E) (TD 2, ex. 3 à 6).",steps:[
 Q("Que faut-il écrire entre 1 et ℕ ?",["1 ∈ ℕ","1 ⊂ ℕ","1 = ℕ"],0,"1 est un élément : on écrit ∈. {1} est une partie : on écrirait {1} ⊂ ℕ."),
 L("Décrire un ensemble",`<ul><li><b>En extension</b> : on liste les éléments, {1, 2, 4, −1}.</li><li><b>En compréhension</b> : {x ∈ E | P(x)}, par exemple {x ∈ ℝ | x² &lt; 3}.</li><li><b>Paramétré</b> : {f(t) | t ∈ T}, par exemple {2k + 1 | k ∈ ℤ} (les impairs).</li></ul><p><b>x ∈ A</b> : x est un élément de A. <b>A ⊂ B</b> : tout élément de A est dans B, c'est-à-dire ∀x ∈ A, x ∈ B. ∅ ⊂ E et E ⊂ E pour tout E.</p><p><b>A = B</b> ⇔ A ⊂ B et B ⊂ A (double inclusion).</p>`),
 Q("{2, 3} … ℕ : quel symbole ?",["⊂","∈","="],0,"{2, 3} est un ensemble de nombres, dont tous les éléments sont dans ℕ : c'est une partie de ℕ.",{diag:false}),
 L("Parties et produit",`<ul><li><b>P(E)</b> : l'ensemble de toutes les parties de E. P({a, b}) = {∅, {a}, {b}, {a, b}}. Si E a n éléments, P(E) en a <b>2ⁿ</b>.</li><li>A ∈ P(E) ⇔ A ⊂ E.</li><li><b>Produit cartésien</b> : A × B = {(a, b) | a ∈ A, b ∈ B}, les couples. ℝ² = ℝ × ℝ est le plan.</li></ul>`),
 Q("C = {2, 5}. Laquelle est vraie ?",["C ∈ P(ℕ)","C ∈ ℕ","C ⊂ P(ℕ)"],0,"C est une partie de ℕ, donc un élément de P(ℕ). Ses éléments (2 et 5) sont des nombres, pas des parties de ℕ : C n'est pas inclus dans P(ℕ)."),
 Q("Combien d'éléments a P({1, 2, 3, 4}) ?",["16","4","8","12"],0,"2⁴ = 16 : pour chaque élément, on choisit de le prendre ou non.",{diag:false}),
 P("TD 2, exercices 5 et 6, sur papier",`<p><b>Exercice 5.</b> Écrire explicitement l'ensemble des parties de X = {♡, □, •}.</p><p><b>Exercice 6.</b> Soit A = {0, 1, 8} et B = {{0}, {1, 2}, {1}}. Vrai ou faux ?</p><p>(a) A ∈ ℕ<br>(b) A ∈ P(ℕ)<br>(c) A ⊂ P(ℕ)<br>(d) B ∈ P(ℕ)<br>(e) B ⊂ P(ℕ)</p>`,`<p><b>Exercice 5.</b> P(X) = { ∅, {♡}, {□}, {•}, {♡, □}, {♡, •}, {□, •}, {♡, □, •} }. Il y a 1 + 3 + 3 + 1 = 8 = 2³ parties. Les deux qu'on oublie le plus souvent : l'ensemble vide ∅ et X lui-même.</p><p><b>Exercice 6.</b></p><p><b>(a) Faux.</b> A est un ensemble de nombres, ce n'est pas un entier naturel.</p><p><b>(b) Vrai.</b> A ∈ P(ℕ) veut dire A ⊂ ℕ, et les éléments de A (0, 1 et 8) sont bien des entiers naturels.</p><p><b>(c) Faux.</b> Il faudrait que chaque élément de A soit une partie de ℕ. Or 0, 1 et 8 sont des nombres, pas des ensembles.</p><p><b>(d) Faux.</b> B ∈ P(ℕ) voudrait dire B ⊂ ℕ. Or les éléments de B sont des ensembles ({0}, {1, 2}, {1}), pas des entiers.</p><p><b>(e) Vrai.</b> Chaque élément de B est une partie de ℕ : {0} ⊂ ℕ, {1, 2} ⊂ ℕ et {1} ⊂ ℕ.</p>`,["Ex. 5 : 8 parties, dont ∅ et X lui-même","Ex. 6 : pour « ∈ P(ℕ) », on regarde si c'est une partie de ℕ","Ex. 6 : pour « ⊂ P(ℕ) », on regarde si chaque élément est une partie de ℕ","Les éléments de B sont des ensembles, pas des nombres"],8),
 K("Quelle est la différence entre x ∈ A et A ⊂ B ? Que veut dire A ∈ P(E) ?","x ∈ A : x est un élément de A. A ⊂ B : tout élément de A est dans B (∀x ∈ A, x ∈ B). A ∈ P(E) ⇔ A ⊂ E."),
 K("Comment prouver que deux ensembles A et B sont égaux ?","Double inclusion : A ⊂ B (« Soit x ∈ A, … donc x ∈ B ») et B ⊂ A.")]},

/* ------------------------------------------------------------------ */
{id:"r-operations",t:"Réunion, intersection, différence : prouver",min:14,goal:"Calculer A ∪ B, A ∩ B, A ∖ B, et prouver une égalité d'ensembles (CC2 2023-2024, ex. 3 ; CC 2024-2025, ex. 1).",steps:[
 Q("A = {1, 2, 4}, B = {1, 3, 4}. Que vaut A ∖ B ?",["{2}","{3}","{1, 4}","{2, 3}"],0,"A ∖ B contient les éléments de A qui ne sont pas dans B. On passe A = {1, 2, 4} en revue : 1 est dans B, 2 n'est pas dans B, 4 est dans B. Il ne reste que 2 : A ∖ B = {2}."),
 L("Les opérations",`${box("A ∪ B = {x | x ∈ A ou x ∈ B}    A ∩ B = {x | x ∈ A et x ∈ B}    A ∖ B = {x | x ∈ A et x ∉ B}")}<ul><li>Complémentaire dans E : Ā = E ∖ A.</li><li>De Morgan pour les ensembles : complémentaire de (A ∪ B) = Ā ∩ B̄ ; de (A ∩ B) = Ā ∪ B̄.</li></ul><p>Exemple (CC 2024-2025) : A = ℝ₋ = ]−∞, 0] et B = {x | x² ≥ 2} = ]−∞, −√2] ∪ [√2, +∞[. A ∪ B = ]−∞, 0] ∪ [√2, +∞[, A ∩ B = ]−∞, −√2], A ∖ B = ]−√2, 0], B ∖ A = [√2, +∞[.</p>`),
 Q("Avec ces A et B, que vaut A ∩ B ?",["]−∞, −√2]","]−∞, 0]","[√2, +∞[","∅"],0,"A ∩ B contient les nombres qui sont dans A et dans B : négatifs ou nuls (A), et de carré au moins 2 (B). B = ]−∞, −√2] ∪ [√2, +∞[ ; la partie négative de B est ]−∞, −√2]. Donc A ∩ B = ]−∞, −√2]."),
 L("Prouver une égalité d'ensembles",`<p>Deux méthodes :</p><ul><li><b>Double inclusion</b> : « Soit x ∈ A. … Donc x ∈ B. » Puis l'inverse.</li><li><b>Par équivalences sur un élément</b> : x ∈ A ⇔ … ⇔ x ∈ B, en traduisant ∪, ∩, ∖ par « ou », « et », « et non », puis en utilisant la logique.</li></ul><p>Exemple : A ∪ B = A ∩ B ⇔ A = B. Si A ∪ B = A ∩ B : A ⊂ A ∪ B = A ∩ B ⊂ B, et de même B ⊂ A.</p>`),
 S("CC2 2023-2024, ex. 3 : A Δ B = (A ∪ B) ∖ (A ∩ B)","Avec A Δ B = (A ∖ B) ∪ (B ∖ A). Par double inclusion.",[
  {w:"⊂ : soit x ∈ A Δ B. Si x ∈ A ∖ B : x ∈ A, donc x ∈ A ∪ B ; x ∉ B, donc x ∉ A ∩ B. Ainsi x ∈ (A ∪ B) ∖ (A ∩ B). Même chose si x ∈ B ∖ A.",why:"Disjonction de cas selon le morceau de la réunion."},
  {w:"⊃ : soit x ∈ (A ∪ B) ∖ (A ∩ B). Alors x ∈ A ou x ∈ B, et x n'est pas dans les deux.",why:"On traduit chaque opération."},
  {w:"Si x ∈ A : comme x n'est pas dans les deux, x ∉ B, donc x ∈ A ∖ B. Si x ∈ B : de même x ∈ B ∖ A. Dans les deux cas, x ∈ A Δ B.",why:"Disjonction de cas."},
  {w:"Par double inclusion, A Δ B = (A ∪ B) ∖ (A ∩ B).",why:"Conclusion."}]),
 Q("Pour montrer A ⊂ B, on commence par…",["Soit x ∈ A.","Soit x ∈ B.","Supposons A = B."],0,"On prend un élément quelconque de A et on montre qu'il est dans B."),
 P("TD 2, exercice 4 et exercice 14 (b), sur papier",`<p><b>Exercice 4.</b> On pose A = {1, 2, 4}, B = {1, 3, 4} et C = [−2, 4[. Déterminer les ensembles A ∪ B, A ∪ C, B ∪ C, A ∩ B, A ∩ C, B ∩ C, A ∖ B, C ∖ A, C ∩ ℤ et C ∩ ℕ.</p><p><b>Exercice 14.</b> Soit A et B deux parties d'un ensemble E. Démontrer l'énoncé suivant : (b) A ⊂ B ⇔ A ∩ B̄ = ∅. (Le (a) a servi d'exemple dans la leçon. B̄ désigne le complémentaire de B dans E.)</p>`,`<p><b>Exercice 4.</b> Attention : C est un intervalle (tous les réels de −2 inclus à 4 exclu).</p><ul><li>A ∪ B = {1, 2, 3, 4}.</li><li>A ∪ C = [−2, 4] : 1 et 2 sont déjà dans C ; on ajoute 4, qui ferme l'intervalle.</li><li>B ∪ C = [−2, 4], pour la même raison.</li><li>A ∩ B = {1, 4}.</li><li>A ∩ C = {1, 2} : 4 n'est pas dans C.</li><li>B ∩ C = {1, 3}.</li><li>A ∖ B = {2}.</li><li>C ∖ A = [−2, 1[ ∪ ]1, 2[ ∪ ]2, 4[ : on enlève 1 et 2 de l'intervalle.</li><li>C ∩ ℤ = {−2, −1, 0, 1, 2, 3}.</li><li>C ∩ ℕ = {0, 1, 2, 3}.</li></ul><p><b>Exercice 14 (b).</b></p><ul><li><b>(⇒)</b> Supposons A ⊂ B. Par l'absurde, supposons qu'il existe x ∈ A ∩ B̄. Alors x ∈ A, donc x ∈ B (car A ⊂ B). Mais x ∈ B̄, donc x ∉ B. Contradiction. Donc A ∩ B̄ = ∅.</li><li><b>(⇐)</b> Supposons A ∩ B̄ = ∅. Soit x ∈ A. Si on avait x ∉ B, alors x serait dans A ∩ B̄, qui est vide : impossible. Donc x ∈ B. Ainsi A ⊂ B.</li></ul>`,["Ex. 4 : les crochets ouverts ou fermés sont justes (4 n'est pas dans C, mais il est dans A)","Ex. 4 : C ∖ A s'écrit avec trois intervalles","Ex. 14 : les deux sens de l'équivalence sont traités séparément","Ex. 14 : « Soit x ∈ A » pour montrer l'inclusion"],12),
 K("Que veulent dire x ∈ A ∪ B, x ∈ A ∩ B et x ∈ A ∖ B ?","x ∈ A ou x ∈ B ; x ∈ A et x ∈ B ; x ∈ A et x ∉ B. Complémentaire de A ∪ B = Ā ∩ B̄."),
 K("Quelles sont les deux méthodes pour prouver une égalité entre deux ensembles ?","Double inclusion (« Soit x ∈ A … donc x ∈ B », puis l'inverse), ou équivalences sur un élément x.")]},

/* ------------------------------------------------------------------ */
{id:"r-image",t:"Applications : image et image réciproque",min:14,goal:"Calculer f(A) et f⁻¹(B), et prouver f(f⁻¹(B)) ⊂ B : l'exercice 1 du CC2 2025-2026.",steps:[
 Q("f(x) = x² sur ℝ. Que vaut f⁻¹({4}) ?",["{−2, 2}","{16}","{2}","∅"],0,"f⁻¹({4}) est l'ensemble des x dont l'image est 4 : x² = 4 donne x = 2 ou x = −2."),
 L("Les définitions",`<p>Une application f : E → F associe à chaque x de E <b>un unique</b> f(x) de F.</p>${box("f(A) = {f(x) | x ∈ A} = {y ∈ F | ∃x ∈ A, y = f(x)}   (image directe de A ⊂ E)")}${box("f⁻¹(B) = {x ∈ E | f(x) ∈ B}   (image réciproque de B ⊂ F)")}<ul><li>f(A) est une partie de F ; f⁻¹(B) est une partie de E.</li><li>f⁻¹(B) existe toujours, même si f n'est pas bijective : c'est l'ensemble des antécédents.</li></ul>`),
 Q("f(x) = x², A = ℝ₋. Que vaut f(A) ?",["[0, +∞[","]−∞, 0]","{0}","ℝ"],0,"Les carrés des négatifs : tous les réels positifs (CC 2024-2025, ex. 1c)."),
 Q("f(x) = x², A = ℝ₋. Que vaut f⁻¹(A) ?",["{0}","]−∞, 0]","∅","ℝ"],0,"f⁻¹(A) est l'ensemble des x dont l'image est dans A, c'est-à-dire tels que f(x) = x² soit négatif ou nul. Un carré est toujours ≥ 0, et il vaut 0 seulement pour x = 0. Donc f⁻¹(A) = {0}."),
 S("CC2 2025-2026, exercice 1 (b) et (c)","L'énoncé : « Soit f : E → F une application. (b) Montrer que pour toute partie B de F, f(f⁻¹(B)) ⊂ B. (c) Justifier que l'inclusion réciproque est fausse en donnant un contre-exemple. » La rédaction est celle du corrigé officiel.",[
  {w:"Soit B une partie de F. Soit y ∈ F. Supposons que y ∈ f(f⁻¹(B)) et montrons que y ∈ B.",why:"Pour montrer une inclusion, on prend un élément de l'ensemble de gauche."},
  {w:"y ∈ f(f⁻¹(B)) signifie qu'il existe x ∈ f⁻¹(B) tel que f(x) = y.",why:"On traduit l'appartenance à une image directe."},
  {w:"Et x ∈ f⁻¹(B) signifie que f(x) ∈ B. Donc y = f(x) ∈ B. On a montré f(f⁻¹(B)) ⊂ B.",why:"On traduit l'appartenance à une image réciproque."},
  {w:"(c) Prenons f : ℝ → ℝ, x ↦ x² et B = [−1, 1]. Alors f⁻¹([−1, 1]) = [−1, 1] et f([−1, 1]) = [0, 1] : B n'est pas inclus dans f(f⁻¹(B)).",why:"Il suffit d'une application non surjective et d'un B qui contient un élément sans antécédent (ici −1)."}]),
 Q("Pour montrer f(A₁ ∩ A₂) ⊂ f(A₁) ∩ f(A₂), on commence par…",["Soit y ∈ f(A₁ ∩ A₂) : il existe x ∈ A₁ ∩ A₂ tel que y = f(x)","Soit x ∈ A₁ : alors f(x) ∈ f(A₁)","Supposons f injective : sinon l'inclusion est fausse","Soit y ∈ f(A₁) ∩ f(A₂) : y = f(x₁) = f(x₂)"],0,"Puis x ∈ A₁ donne y ∈ f(A₁), x ∈ A₂ donne y ∈ f(A₂). L'égalité est fausse en général : x², A₁ = {−1}, A₂ = {1} (TD 3, ex. 8). Pour montrer E ⊂ F, on part d'un élément de E (ici f(A₁ ∩ A₂)), pas de F. Et l'inclusion est vraie pour toute f, injective ou non."),
 P("CC2 2025-2026, exercice 3 (a), sur papier",`<p>Soit f l'application f : ℤ × ℤ → ℤ, (a, b) ↦ 2a + b, et g l'application g : ℤ → ℤ, n ↦ n/2 si n est pair, 0 si n est impair.</p><p>(a) Déterminer : f(ℤ × {1}), f⁻¹({0}), g(ℤ), et g⁻¹(ℕ*)</p>`,`<span class="who">Corrigé officiel (manuscrit), recopié</span><p>f(ℤ × {1}) = {2a + 1 | a ∈ ℤ} = l'ensemble des entiers relatifs impairs.</p><p>f⁻¹({0}) = {(a, b) ∈ ℤ² | 2a + b = 0} = {(a, b) ∈ ℤ² | b = −2a} = {(a, −2a) | a ∈ ℤ}.</p><p>g(ℤ) = ℤ (car ∀n ∈ ℤ, g(2n) = n).</p><p>g⁻¹(ℕ*) = {n ∈ ℤ | g(n) ∈ ℕ*} = {2k | k ∈ ℕ*} = l'ensemble des entiers pairs strictement positifs. (Les impairs sont exclus : leur image est 0.)</p>`,["Chaque ensemble est décrit précisément (avec un paramètre, ou en mots)","f⁻¹({0}) est un ensemble de couples","g(ℤ) = ℤ : un antécédent est donné pour tout entier n","g⁻¹(ℕ*) : les impairs sont exclus, car leur image est 0"],12),
 K("Pour une application f : E → F, quelles sont les définitions de l'image directe f(A) et de l'image réciproque f⁻¹(B) ?","f(A) = {f(x) | x ∈ A} ⊂ F ; f⁻¹(B) = {x ∈ E | f(x) ∈ B} ⊂ E. f⁻¹(B) existe même si f n'est pas bijective."),
 K("Pour une application f et une partie B de l'ensemble d'arrivée, quel lien y a-t-il entre f(f⁻¹(B)) et B ?","f(f⁻¹(B)) ⊂ B, et l'égalité peut être fausse : pour x ↦ x² et B = [−1, 1], on trouve f(f⁻¹(B)) = [0, 1].")]},

/* ------------------------------------------------------------------ */
{id:"r-injective",t:"Injective, surjective, bijective",min:15,goal:"Dire, en justifiant, si une application est injective, surjective, bijective (CC2 2024-2025 ex. 2 ; 2025-2026 ex. 3c ; TD 3, ex. 7 et 10).",steps:[
 Q("f : ℝ → ℝ, x ↦ x². Est-elle injective ?",["Non : f(1) = f(−1)","Oui : f est croissante, donc injective","Oui : chaque x a une seule image x²"],0,"Injective veut dire : deux nombres différents ont toujours des images différentes. Ici f(−1) = 1 = f(1), alors que −1 ≠ 1. Donc f n'est pas injective. x² n'est croissante que sur ℝ₊. Et « une seule image par x », c'est être une fonction, pas être injective."),
 L("Les trois définitions",`<ul><li><b>Injective</b> : deux éléments différents ont des images différentes. ∀x, x′ ∈ E, f(x) = f(x′) ⇒ x = x′. (Chaque y a <b>au plus</b> un antécédent.)</li><li><b>Surjective</b> : tout élément de F est atteint. ∀y ∈ F, ∃x ∈ E, f(x) = y. (Au <b>moins</b> un antécédent.)</li><li><b>Bijective</b> : les deux. (<b>Exactement</b> un antécédent.) Elle a alors une réciproque f⁻¹ : F → E.</li></ul>`),
 Q("f : ℕ → ℕ, n ↦ n + 1. Laquelle est vraie ?",["Injective, pas surjective (0 n'a pas d'antécédent)","Bijective : chaque n a son successeur, et réciproquement","Surjective, pas injective : tout entier est un n + 1"],0,"n + 1 = m + 1 donne n = m. Mais n + 1 = 0 n'a pas de solution dans ℕ (TD 3, ex. 7)."),
 L("Les méthodes",`<ul><li><b>Prouver injective</b> : « Soient x, x′ tels que f(x) = f(x′). … Donc x = x′. »</li><li><b>Réfuter injective</b> : deux éléments différents de même image (f(1) = f(−1)).</li><li><b>Prouver surjective</b> : « Soit y ∈ F. Posons x = … ∈ E. Alors f(x) = y. » (Résoudre f(x) = y.)</li><li><b>Réfuter surjective</b> : un y sans antécédent, en le justifiant.</li></ul><p>Les ensembles de départ et d'arrivée comptent : x ↦ x² est bijective de ℝ₊ dans ℝ₊, mais ni injective ni surjective de ℝ dans ℝ.</p>`),
 S("CC du 15 novembre 2024, exercice 2","L'énoncé : « Soit f l'application f : ℕ → ℕ, x ↦ 2x, et g l'application g : ℕ → ℕ, x ↦ x/2 si x est pair, 0 si x est impair. (a) Déterminer g ∘ f et f ∘ g. (b) Les fonctions f et g sont-elles injectives ? surjectives ? bijectives ? Justifier soigneusement. » La rédaction est celle du corrigé officiel.",[
  {w:"g ∘ f : x ↦ g(f(x)) = g(2x) = (1/2) × 2x = x, car 2x est toujours pair. Donc g ∘ f = Id<sub>ℕ</sub>.",why:"(a) g ∘ f : on applique f d'abord, puis g."},
  {w:"f ∘ g : si x est pair, f(x/2) = 2 × (x/2) = x ; si x est impair, f(0) = 0. Donc (f ∘ g)(x) = x si x est pair, 0 si x est impair.",why:"(a) On traite les deux cas de la définition de g. f ∘ g n'est pas l'identité."},
  {w:"f : 1 n'a pas d'antécédent par f, donc f n'est pas surjective. Si f(x) = f(y), alors 2x = 2y, donc x = y : f est injective. Conclusion : f est injective, non surjective, donc non bijective.",why:"(b) Un élément sans antécédent pour « non surjective » ; la méthode « f(x) = f(y) ⇒ x = y » pour « injective »."},
  {w:"g : tous les impairs ont la même image, 0, donc g n'est pas injective. Soit y ∈ ℕ : si on prend x = 2y (pair), on a g(x) = y, donc g est surjective. Conclusion : g est surjective, non injective, donc non bijective.",why:"(b) Deux éléments de même image ; puis un antécédent donné pour tout y."}]),
 Q("f : ℤ × ℤ → ℤ, (a, b) ↦ 2a + b est-elle injective ?",["Non : f(0, 0) = f(1, −2) = 0","Oui","Oui, car 2a + b détermine a"],0,"Deux couples différents, même image (CC2 2025-2026, ex. 3c). Elle est surjective : f(0, m) = m."),
 Q("φ : ℚ → ℚ, x ↦ −x/2 + 1 est bijective. Quelle est sa réciproque ?",["y ↦ 2 − 2y","y ↦ −y/2 + 1","y ↦ 2y − 2","y ↦ 1/y"],0,"y = −x/2 + 1 ⇔ x = 2(1 − y) = 2 − 2y, qui est bien dans ℚ (TD 3, ex. 7)."),
 P("TD 3, exercice 10, sur papier",`<p>Soit f : ℕ → ℕ et g : ℕ → ℕ les applications définies par : ∀k ∈ ℕ, f(k) = 2k et g(k) = k/2 si k est pair, (k − 1)/2 si k est impair.</p><p>(a) Étudier l'injectivité, la surjectivité et la bijectivité de f et de g.</p><p>(b) Préciser les applications g ∘ f et f ∘ g. Étudier leur injectivité, surjectivité et bijectivité.</p><p>(Attention : ce g n'est pas celui du CC de 2024. Ici un impair k est envoyé sur (k − 1)/2, pas sur 0.)</p>`,`<span class="who">Corrigé officiel (Moodle, « Quelques corrections du TD3 »), recopié</span><p><b>a)</b> Pour (k₁, k₂) ∈ ℕ² : f(k₁) = f(k₂) ⇒ 2k₁ = 2k₂ ⇒ k₁ = k₂, donc <b>f est injective</b>.<br>Pour tout k ∈ ℕ, f(k) = 2k, donc f(ℕ) = {2k : k ∈ ℕ} = 2ℕ, l'ensemble des entiers naturels pairs. De ce fait f(ℕ) ≠ ℕ : <b>f n'est pas surjective</b> (donc pas bijective).<br><b>g n'est pas injective</b>, car (par exemple) g(2) = g(3) = 1.<br><b>g est surjective</b>, car pour tout k ∈ ℕ, g(2k) = k, donc g(ℕ) = ℕ. Elle n'est pas bijective.</p><p><b>b)</b> Pour tout k ∈ ℕ, (g ∘ f)(k) = g(2k) = 2k/2 = k. Donc <b>g ∘ f = id<sub>ℕ</sub></b>, qui est bijective.</p><p>Si k est pair : (f ∘ g)(k) = f(k/2) = 2 × (k/2) = k. Si k est impair : (f ∘ g)(k) = f((k − 1)/2) = 2 × (k − 1)/2 = k − 1. En résumé, pour tout l ∈ ℕ : (f ∘ g)(2l) = (f ∘ g)(2l + 1) = 2l.<br><b>f ∘ g n'est ni injective</b> (par exemple (f ∘ g)(2) = (f ∘ g)(3)), <b>ni surjective</b>, car (f ∘ g)(ℕ) = 2ℕ ≠ ℕ.</p>`,["Chaque « oui » est prouvé (f(k₁) = f(k₂) ⇒ k₁ = k₂ ; un antécédent pour tout k)","Chaque « non » est justifié par un exemple chiffré","Les deux cas (k pair, k impair) sont traités pour f ∘ g","L'ordre de la composition est respecté : (g ∘ f)(k) = g(f(k))"],15),
 K("Quelles sont les définitions d'une application injective, surjective, bijective ?","Injective : f(x) = f(x′) ⇒ x = x′ (au plus un antécédent). Surjective : ∀y, ∃x, f(x) = y (au moins un). Bijective : exactement un."),
 K("Comment montrer qu'une application n'est pas injective ? Qu'elle n'est pas surjective ?","Injectivité : deux éléments différents de même image. Surjectivité : un élément d'arrivée sans antécédent.")]},

/* ------------------------------------------------------------------ */
{id:"r-composition",t:"Composition et preuves sur les applications",min:14,goal:"Composer des applications et prouver « g ∘ f injective ⇒ f injective » (CC2 2023-2024, ex. 4 ; TD 3, ex. 9 et 11).",steps:[
 Q("Pour calculer (g ∘ f)(x), on applique…",["d'abord f, puis g","d'abord g, puis f","f et g en même temps"],0,"(g ∘ f)(x) = g(f(x)) : f agit en premier, comme on lit de droite à gauche."),
 L("La composée",`<p>Si f : E → F et g : F → G, alors <b>g ∘ f : E → G</b>, x ↦ g(f(x)). Il faut que l'arrivée de f soit le départ de g (ou y soit incluse).</p><ul><li>f : ℤ × ℤ → ℤ et g : ℤ → ℤ : g ∘ f existe (de ℤ × ℤ dans ℤ), mais <b>f ∘ g n'existe pas</b> : g arrive dans ℤ alors que f part de ℤ × ℤ.</li><li>En général, g ∘ f ≠ f ∘ g.</li></ul>`),
 Q("f : ℤ × ℤ → ℤ, g : ℤ → ℤ. Laquelle existe ?",["g ∘ f","f ∘ g","Les deux","Aucune"],0,"g ∘ f applique f (qui donne un entier), puis g. f ∘ g demanderait de donner un entier à f, qui attend un couple (CC2 2025-2026, ex. 3b)."),
 L("Les deux résultats à savoir prouver",`<ul><li><b>g ∘ f injective ⇒ f injective</b> : soient x, x′ tels que f(x) = f(x′). Alors g(f(x)) = g(f(x′)), c'est-à-dire (g ∘ f)(x) = (g ∘ f)(x′), donc x = x′.</li><li><b>g ∘ f surjective ⇒ g surjective</b> : soit z ∈ G. Il existe x ∈ E tel que g(f(x)) = z. Alors y = f(x) ∈ F vérifie g(y) = z.</li></ul><p>À retenir : c'est la <b>première</b> appliquée (f) qui hérite de l'injectivité, la <b>dernière</b> (g) de la surjectivité.</p>`),
 Q("Si g ∘ f est surjective, que peut-on dire ?",["g est surjective","f est surjective","f est injective"],0,"Si g ∘ f est surjective, tout z est de la forme g(f(x)) pour un certain x. Donc z = g(y) avec y = f(x) : tout z est atteint par g. Conclusion : g est surjective. On ne peut rien dire de f en général."),
 S("TD 3, ex. 11 : f(f(x) − 1) = x + 1 pour tout x ⇒ f bijective","f : ℝ → ℝ vérifie ∀x ∈ ℝ, f(f(x) − 1) = x + 1.",[
  {w:"Injective : soient x, x′ avec f(x) = f(x′). Alors f(x) − 1 = f(x′) − 1, donc f(f(x) − 1) = f(f(x′) − 1), c'est-à-dire x + 1 = x′ + 1, donc x = x′.",why:"On applique la relation aux deux nombres."},
  {w:"Surjective : soit y ∈ ℝ. Avec x = y − 1 : f(f(y − 1) − 1) = (y − 1) + 1 = y. Donc y a pour antécédent f(y − 1) − 1.",why:"On choisit x pour que x + 1 = y."},
  {w:"f est injective et surjective : elle est bijective.",why:"Conclusion."}]),
 P("CC2 2023-2024, exercice 4 (8 points), sur papier",`<p>Soient f : A → B et g : B → C deux applications. <b>Démontrer soigneusement</b> les propriétés suivantes :</p><p>(a) Si g ∘ f est surjective, alors g est surjective.</p><p>(b) Si g ∘ f est injective, alors f est injective.</p><p>(c) On suppose maintenant que les ensembles A et C coïncident, et que f ∘ g ∘ f est bijective. Montrer que f est bijective.</p><p>(d) Soit f : ℝ → ℝ une fonction qui vérifie : ∀x ∈ ℝ, f(2f(x) + 4) = x − 1. Montrer que f est bijective.</p><p>((a) et (b) sont les deux preuves de la leçon : au CC, il faut savoir les refaire de mémoire.)</p>`,`<span class="who">Corrigé officiel, recopié</span><p>(a) et (b) sont des résultats vus en cours et revus en TD. Rappelons les preuves.</p><p><b>(a)</b> Supposons que g ∘ f est surjective. Soit z ∈ C. On doit montrer qu'il existe y ∈ B tel que g(y) = z. Par surjectivité de g ∘ f, on sait qu'il existe x ∈ A tel que (g ∘ f)(x) = z. Posons alors y = f(x). On a g(y) = g(f(x)) = (g ∘ f)(x) = z. Donc g est surjective.</p><p><b>(b)</b> Supposons que g ∘ f est injective. On doit montrer que si x, x′ ∈ A vérifient f(x) = f(x′), alors x = x′. Soient donc x, x′ ∈ A tels que f(x) = f(x′). En composant à gauche par g, on obtient (g ∘ f)(x) = (g ∘ f)(x′). Par injectivité de g ∘ f, on déduit x = x′. Donc f est injective.</p><p><b>(c)</b> Puisque f ∘ g ∘ f est bijective, elle est surjective et injective. Étant surjective, (a) et l'égalité f ∘ g ∘ f = f ∘ (g ∘ f) impliquent que f est surjective ; f ∘ g ∘ f étant injective, (b) et l'égalité f ∘ g ∘ f = (f ∘ g) ∘ f impliquent que f est aussi injective. En conclusion, f est bien bijective.</p><p><b>(d)</b> Pour tous x, y ∈ ℝ, posons h(x) = f(2f(x) + 4) et g(y) = 2y + 4. L'hypothèse dit que pour tout x ∈ ℝ on a h(x) = f(g(f(x))), c'est-à-dire h = f ∘ g ∘ f, et h(x) = x − 1. Donc h est bijective, et alors (c) implique que f est bijective.</p>`,["(a) : « Soit z ∈ C », puis un antécédent y = f(x) est donné","(b) : « Soient x, x′ tels que f(x) = f(x′) », puis on compose par g","(c) : les deux parenthésages f ∘ (g ∘ f) et (f ∘ g) ∘ f sont écrits, et (a), (b) sont cités","(d) : on reconnaît f ∘ g ∘ f avec g(y) = 2y + 4, et x ↦ x − 1 est bijective"],15),
 K("Si g ∘ f est injective, que peut-on dire de f ou de g ? Et si g ∘ f est surjective ?","g ∘ f injective ⇒ f injective (la première) ; g ∘ f surjective ⇒ g surjective (la dernière)."),
 K("À quelle condition la composée g ∘ f existe-t-elle ? Que vaut (g ∘ f)(x) ?","Il faut que f arrive là où g part : f : E → F, g : F → G donnent g ∘ f : E → G, x ↦ g(f(x)).")]}
];
})();
